/** True when consuming `requested` more units would breach the quota. */
export function wouldExceedLimit(
  plan: PlanId,
  resource: LimitedResource,
  used: number,
  requested = 1,
): boolean {
  return used + requested > getLimit(plan, resource);
}

export const BYTES_PER_MB = 1024 * 1024;

/**
 * The `storageMb` charge for one file: its size rounded up to whole megabytes,
 * so a 0.3 MB file costs 1 MB and a 1.5 MB file costs 2 MB. Uploads, deletes
 * and the usage recount all charge through here so they agree.
 */
export function storageMbCharge(sizeBytes: number): number {
  return Math.ceil(sizeBytes / BYTES_PER_MB);
}

